import{z as s,x as p,o as i,c as B,q as A,j as o,D as t,d as e,s as l,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"货币政策规则","description":"","frontmatter":{"title":"货币政策规则","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mt-policy-rules.md","filePath":"econ/mt-policy-rules.md","lastUpdated":1791063341000}'),d={name:"econ/mt-policy-rules.md"};function c(m,E,h,_,D,C){const r=p("Mermaid");return i(),B("div",null,[E[2]||(E[2]=A('<h1 id="货币政策规则" tabindex="-1">货币政策规则 <a class="header-anchor" href="#货币政策规则" aria-label="Permalink to &quot;货币政策规则&quot;">​</a></h1><div class="epigraph"><p>规则优于权变，不是因为规则更聪明，而是因为承诺可以被第三方核验；不可核验的承诺只是意图。</p><footer>—— 据 Kydland–Prescott 1977；Taylor, Carnegie–Rochester 1993 整理</footer></div><p><a href="/econ/mt-optimal-inflation">上一课</a>把目标定在正的小值，并指出目标越低、下限绑得越早。缺口随之而来：从目标到实际利率之间需要一张映射，而央行每一期都有重新选择的诱惑——权变的均衡是通胀偏高而无产出收益，这是<a href="/econ/time-inconsistency">时间不一致与承诺</a>与<a href="/econ/kydland-prescott">Kydland–Prescott 规则优于权变</a>已经铺好的结论。本课不再论证「要承诺」，而是深化「承诺长什么样」：工具规则与目标规则的分工、泰勒原理的确定性角色、以及最优承诺的起点问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「按规则办事」仍是一个谱系。基线课的<a href="/econ/taylor-rule">泰勒规则</a>给出最著名的一条：</p> \\[i_t = r^{*} + \\pi_t + \\phi_\\pi(\\pi_t - \\pi^{*}) + \\phi_y\\,\\tilde{y}_t, \\]<p>系数 \\(\\phi_\\pi = 1.5\\)、\\(\\phi_y = 0.5\\) 拟合的是 1987 至 1992 年的美国数据。缺口在于：这是历史拟合，不是福利最优；且同一承诺可以写在不同的变量上——直接给利率公式，还是只给通胀目标的达成条件。选哪一种，决定了规则在模型更替时的存活能力。</p><p><span class="marginnote">数字实例：目标通胀 2%，实际通胀 4%，产出缺口为 0。按 \\(\\phi_\\pi=1.5\\)，名义利率应为 \\(r^{*}+4\\%+1.5\\times(4\\%-2\\%)=r^{*}+7\\%\\)——通胀每多 1 个点，利率要加 1.5 个点，实际利率才能真正收紧。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工具规则直接规定工具 \\(i_t\\) 对可观测变量的反应，央行与公众都能逐期核验。目标规则只规定目标变量的条件，典型形式是：通胀的预期路径必须等于目标，加上损失函数最小化的一阶条件。二者的分工是：工具规则把承诺写死在反应函数上，简单、可审计；目标规则把承诺写在损失函数上，模型换了、承诺还在。Woodford 2003 倾向后者，理由正是模型的不可靠性。</p><p><span class="marginnote">直觉类比：工具规则像导航逐秒告诉你「现在打多少度方向盘」；目标规则像只规定「天黑前必须到达」——路改了（模型换了），导航作废，但「天黑前到达」这个承诺依然有效。</span></p><p>承诺的起点同样要选。若规则从「今天」开始执行，开局一期存在一次性通胀的诱惑——旧债已定，意外通胀是免费午餐。<strong>永恒视角</strong>（timeless perspective）要求规则当作无限过去就已存在来评估，掐掉这个开局红利；它是把巴罗–戈登式偏误从稳态推到全路径的修正。</p>',12)),(i(),o(n,null,{default:t(()=>[l(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20DISC%5B%22%E6%9D%83%E5%8F%98%EF%BC%9A%E6%AF%8F%E6%9C%9F%E9%87%8D%E9%80%89%22%5D%20--%3E%20BIAS%5B%22%E9%80%9A%E8%83%80%E5%81%8F%E8%AF%AF%EF%BC%8C%E6%97%A0%E4%BA%A7%E5%87%BA%E6%94%B6%E7%9B%8A%22%5D%0A%20%20DISC%20--%3E%20IR%5B%22%E7%AE%80%E5%8D%95%E5%B7%A5%E5%85%B7%E8%A7%84%E5%88%99%EF%BC%9A%E6%B3%B0%E5%8B%92%E5%9E%8B%22%5D%0A%20%20DISC%20--%3E%20TR%5B%22%E7%9B%AE%E6%A0%87%E8%A7%84%E5%88%99%EF%BC%9A%E9%A2%84%E6%9C%9F%E8%B7%AF%E5%BE%84%E7%AD%89%E4%BA%8E%E7%9B%AE%E6%A0%87%22%5D%0A%20%20IR%20--%3E%20TP%5B%22%E6%B0%B8%E6%81%92%E8%A7%86%E8%A7%92%E7%9A%84%E6%9C%80%E4%BC%98%E6%89%BF%E8%AF%BA%22%5D%0A%20%20TR%20--%3E%20TP%0A%20%20TP%20--%3E%20OUT%5B%22%E5%9D%87%E8%A1%A1%E9%80%9A%E8%83%80%E6%8E%A5%E8%BF%91%E7%9B%AE%E6%A0%87%EF%BC%8C%E6%89%BF%E8%AF%BA%E5%8F%AF%E6%A0%B8%E9%AA%8C%22%5D%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("规则之所以能钉住价格路径，核心是"),a("a",{href:"/econ/taylor-principle"},"泰勒原理"),e("的确定性角色：要求 \\(\\phi_\\pi \\gt 1\\)。通胀预期上升一个百分点，名义利率须上升超过一个百分点，实际利率才被推高，通胀预期才被压回；若 \\(\\phi_\\pi \\lt 1\\)，通胀上升反而降低实际利率，需求扩张反过来坐实通胀——均衡不唯一，价格水平由任意的预期波动决定。确定性不是福利计算，而是规则能生效的前提条件：先有唯一均衡，才谈得上均衡好还是坏。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"常见误区：把 \\(\\phi_\\pi\\gt 1\\) 当成「态度强硬」。它是数学上的确定性条件：系数不足 1 时通胀上升反而压低实际利率，均衡不唯一——价格由预期波动任意决定，再强硬的表态也钉不住。")],-1)),(i(),o(n,null,{default:t(()=>[l(r,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E9%80%9A%E8%83%80%E9%A2%84%E6%9C%9F%E4%B8%8A%E5%8D%87%201%20%E4%B8%AA%E7%99%BE%E5%88%86%E7%82%B9%22%5D%20--%3E%20Q%7B%22phi_pi%20%E6%98%AF%E5%90%A6%E5%A4%A7%E4%BA%8E%201%EF%BC%9F%22%7D%0A%20%20Q%20--%20%22%E6%98%AF%22%20--%3E%20NOM%5B%22%E5%90%8D%E4%B9%89%E5%88%A9%E7%8E%87%E5%8D%87%E8%B6%85%E8%BF%87%201%20%E4%B8%AA%E7%99%BE%E5%88%86%E7%82%B9%22%5D%0A%20%20NOM%20--%3E%20REAL%5B%22%E5%AE%9E%E9%99%85%E5%88%A9%E7%8E%87%E8%A2%AB%E6%8E%A8%E9%AB%98%22%5D%0A%20%20REAL%20--%3E%20COOL%5B%22%E9%9C%80%E6%B1%82%E9%99%8D%E6%B8%A9%EF%BC%8C%E9%A2%84%E6%9C%9F%E8%A2%AB%E5%8E%8B%E5%9B%9E%EF%BC%9A%E5%9D%87%E8%A1%A1%E5%94%AF%E4%B8%80%22%5D%0A%20%20Q%20--%20%22%E5%90%A6%22%20--%3E%20NOM2%5B%22%E5%90%8D%E4%B9%89%E5%88%A9%E7%8E%87%E5%8D%87%E4%B8%8D%E8%B6%B3%201%20%E4%B8%AA%E7%99%BE%E5%88%86%E7%82%B9%22%5D%0A%20%20NOM2%20--%3E%20REAL2%5B%22%E5%AE%9E%E9%99%85%E5%88%A9%E7%8E%87%E5%8F%8D%E8%80%8C%E4%B8%8B%E9%99%8D%22%5D%0A%20%20REAL2%20--%3E%20SELF%5B%22%E9%9C%80%E6%B1%82%E6%89%A9%E5%BC%A0%E5%9D%90%E5%AE%9E%E9%80%9A%E8%83%80%EF%BC%9A%E8%87%AA%E6%88%91%E5%AE%9E%E7%8E%B0%22%5D%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<p>简单规则在模型不确定下另有优势。最优规则把系数压到对具体模型结构的敏感处，模型一错、规则失效；文献对简单规则稳健性的比较（McCallum 1988 以来）发现，跨模型表现平均较好的往往是系数保守的简单规则。这与上一课的结论一致：目标定得保守，是为了留下犯错的空间；系数取得保守，是为了留下换模型的空间。</p><p>\\(r^{*}\\) 与产出缺口的测量误差是简单规则的常态负担（<a href="/econ/r-star">自然利率 r*</a>）：实时估计的缺口在衰退里系统性偏负，规则会跟着过度宽松。规则的价值不因此取消，但系数的保守性与对状态的平滑处理成为工程要求。</p><p><span class="marginnote">\\(\\phi_\\pi \\gt 1\\) 是局部确定性条件，不保证全局唯一，也不防住缺口测量的误差。1990 年代把泰勒规则的历史拟合当规范处方使用，混淆了「描述了这段历史」与「应该按此执行」两件事。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课的规则只写通胀与产出缺口，没有给金融稳定和供给冲击留权重——把这些塞进同一反应函数，会与<a href="/econ/discretion-commitment">权变对承诺</a>里讨论的新目标混淆，损害可核验性。规则也不是宪法：例外状态需要显式的退出条款，否则规则的每一次破例都要重新议价。下一课处理规则的另一半：无论反应函数多精确，传导都要穿过公众的预期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>承诺有谱系：工具规则可审计，目标规则跨模型存活，永恒视角掐掉开局通胀红利。</li><li>泰勒原理 \\(\\phi_\\pi \\gt 1\\) 是均衡确定性的前提，先于福利评价。</li><li>模型不确定下，系数保守的简单规则比精确最优规则更稳健。</li><li>规则的常态负担是 \\(r^{*}\\) 与缺口的实时测量误差，不是规则本身失效。</li><li>出处：Taylor, Carnegie–Rochester 1993；Kydland–Prescott 1977；Woodford, <em>Interest and Prices</em>, 2003；McCallum 1988。</li></ul>',7))])}const u=s(d,[["render",c]]);export{f as __pageData,u as default};
